sealed class AuditProxy<T> : DispatchProxy {
    protected override object? Invoke(MethodInfo? m, object?[]? args) {
        _sink.Record(_subject.Id, m!.Name, Outcome.Attempt);
        try { var r = m.Invoke(_inner, args); _sink.Record(_subject.Id, m.Name, Outcome.Ok); return r; }
        catch (TargetInvocationException e) { _sink.Record(_subject.Id, m.Name, Outcome.Failed); throw e.InnerException!; }
    }
}

