public sealed class AuditFilter : IAsyncActionFilter {
    public async Task OnActionExecutionAsync(
        ActionExecutingContext ctx, ActionExecutionDelegate next)
    {
        _sink.Record(_subject.Id, ctx.ActionDescriptor.DisplayName!, Outcome.Attempt);
        var executed = await next();
        _sink.Record(_subject.Id, ctx.ActionDescriptor.DisplayName!,
                     executed.Exception is null ? Outcome.Ok : Outcome.Failed);
    }
}
